/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<PdfEventMsg> pdfEvents( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel pdfEventsChannel =
      EventChannel('dev.flutter.pigeon.danaview_pdf.PdfEventsApi.pdfEvents$instanceName', pigeonMethodCodec);
  return pdfEventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as PdfEventMsg;
  });
}
    

